int longestUnique(const std::string& s) {
    std::unordered_map<char, int> count;
    int left = 0, best = 0;
    for (int right = 0; right < (int)s.size(); ++right) {
        count[s[right]]++;
        while (count[s[right]] > 1) {
            count[s[left]]--;
            ++left;
        }
        best = std::max(best, right - left + 1);
    }
    return best;
}

